class Solution {
public:
    int nthMagicalNumber(int n, int a, int b) {
        long long MOD = 1000000007;
        long long lcm = (1LL * a * b) / std::gcd(a, b);
        long long low = 1, high = 1LL * n * min(a, b);
        while (low < high) {
            long long mid = low + (high - low) / 2;
            long long cnt = mid / a + mid / b - mid / lcm;
            if (cnt < n) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low % MOD;
    }
