class Solution {
    private long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public int nthMagicalNumber(int n, int a, int b) {
        long MOD = 1_000_000_007L;
        long lcm = ((long) a * b) / gcd(a, b);
        long low = 1, high = (long) n * Math.min(a, b);
        while (low < high) {
            long mid = low + (high - low) / 2;
            long cnt = mid / a + mid / b - mid / lcm;
            if (cnt < n) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return (int) (low % MOD);
    }
}

var nthMagicalNumber = function(n, a, b) {
    const MOD = 1000000007n;
    function gcd(x, y) {
        return y === 0n ? x : gcd(y, x % y);
    }
    const ba = BigInt(a), bb = BigInt(b), bn = BigInt(n);
    const lcm = (ba * bb) / gcd(ba, bb);
    const minAB = ba < bb ? ba : bb;
    let low = 1n, high = bn * minAB;
    while (low < high) {
        const mid = (low + high) / 2n;
        const cnt = mid / ba + mid / bb - mid / lcm;
        if (cnt < bn) {
            low = mid + 1n;
        } else {
            high = mid;
        }
    }
    return Number(low % MOD);
};
